import{_ as t,o as a,c as o,ak as i}from"./chunks/framework.D6lxc04_.js";const b=JSON.parse('{"title":"Moveable Entity Block 可推动方块实体","description":"","frontmatter":{"title":"Moveable Entity Block 可推动方块实体","prev":false,"next":false},"headers":[],"relativePath":"posts/docs/moveable-entity-block/index.md","filePath":"posts/docs/moveable-entity-block/index.md","lastUpdated":1778064395000}'),l={name:"posts/docs/moveable-entity-block/index.md"};function d(n,e,c,r,s,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="可推动方块实体模块" tabindex="-1">可推动方块实体模块 <a class="header-anchor" href="#可推动方块实体模块" aria-label="Permalink to “可推动方块实体模块”">​</a></h1><p>包 <code>dev.anvilcraft.lib.v2.piston</code> 解决了原版活塞无法推动带方块实体的方块的问题。通过一组 Mixin 和接口，允许方块在移动过程中携带自定义 NBT 数据，并在活塞停止时将数据写回目标位置的方块实体。</p><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to “文档索引”">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./api.html">核心接口</a></td><td><code>IMoveableEntityBlock</code>、<code>IPistonMovingBlockEntityExtension</code></td></tr><tr><td><a href="./usage.html">Mixin 与使用</a></td><td>Mixin 修改点、完整使用示例</td></tr></tbody></table><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>在原版中，活塞推动带方块实体的方块时不会有任何效果。本模块通过注入活塞的移动逻辑：</p><ol><li><strong>移动前</strong> — 调用 <code>clearData</code> 提取方块实体数据</li><li><strong>移动中</strong> — 数据暂存于 <code>PistonMovingBlockEntity</code></li><li><strong>移动结束</strong> — 调用 <code>setData</code> 将数据写回新位置的方块实体</li></ol><p>全过程对服务端透明，无需修改原版活塞核心逻辑。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>所有数据传递在服务端进行，客户端不保留额外数据</li><li><code>clearData</code> 应返回需要保留的自定义数据，而非序列化整个方块实体</li><li><code>IMoveableEntityBlock</code> 继承 <code>EntityBlock</code>，若方块已是 <code>BaseEntityBlock</code> 子类，只需额外实现该接口</li><li>Mixin 优先级 <code>priority = 943</code>，与其他活塞修改模组冲突时可能需要调整</li></ul>',10)])])}const _=t(l,[["render",d]]);export{b as __pageData,_ as default};
